$ErrorActionPreference='Stop'
$js=@'
let sock;try{
const v=await(await fetch("http://127.0.0.1:17447/json/list")).json();let t=v.find(x=>x.url.startsWith("https://www.avito.ru/krasnoyarsk/"));if(!t)throw Error("TAB_NOT_FOUND");
sock=new WebSocket(t.webSocketDebuggerUrl);
const answer=await Promise.race([new Promise((resolve,reject)=>{
sock.addEventListener("open",()=>{sock.send(JSON.stringify({id:22,method:"Runtime.evaluate",params:{expression:"([...document.querySelectorAll('[data-marker=item]')].slice(0,10).map((el,i)=>({i,title:(el.querySelector('h3')?.textContent||'').slice(0,90),href:el.querySelector('a[href]')?.href||'',testId:el.getAttribute('data-item-id')})))",returnByValue:true}}))},{once:true});
sock.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===22)resolve(x.result?.result?.value||{err:x.error?.code})});
sock.addEventListener("error",reject,{once:true})}),new Promise((_,bad)=>setTimeout(()=>bad(Error("TIMEOUT")),5000))]);
console.log(JSON.stringify(answer))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}))}
if(sock)sock.close();process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'avito-simple-titles.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
